/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: subjectId, credit, mbid, subject, subjects, capture
 *   Constants: reviewId, slotA, slotB
 * Tests
 *   - the captured Credits keep stored order, role, phrase and record, and name the entry showing each one
 *   - the label state is none without a label Credit, first when its first label Credit is shown, and other otherwise
 *   - a list is complete only when every primary and featured Artist Credit is shown
 *   - legacy unspecified Credits are captured but shown as no entry, and leave a list complete
 *   - captured entries keep stored Credit order, a featured Artist before a primary one included, and names differing only in case
 *   - a member's attribution state keeps an explicit unknown apart from an absent or unrecognized one
 *   - a member's duration is its exact media duration, else its legacy whole-second text, else unknown
 * @end-catalog */

/**
 * What an existing-Album review captures when metadata lookup is first admitted for it, from Credits and records already read:
 * the pure capture and member durations. The conversion's reads and writes are covered by adminCatalogReview.integration.ts.
 * Every identity and name is synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { catalogReviewCaptureOf, catalogReviewMemberDuration } from '../../src/administration/catalog/adminCatalogReviewCapture';
import { catalogReviewCredits, catalogReviewEntryKey } from '../../src/administration/catalog/adminCatalogReviewService';
import type { CatalogReviewCapturedSubject } from '../../src/administration/catalog/adminCatalogReviewContract';
import type { CatalogCredit } from '../../src/models/catalogCredit';

const reviewId = '0000000000000000000000f1', slotA = '00000009-0000-4000-a000-0000000000f1', slotB = '00000009-0000-4000-a000-0000000000f2';
const subjectId = (n: number) => n.toString(16).padStart(24, '0');
const credit = (creditId: string, subjectType: CatalogCredit['subjectType'], n: number, role: CatalogCredit['role'], joinPhrase?: string): CatalogCredit =>
    ({ creditId, subjectType, subjectId: subjectId(n), role, order: 0, ...(joinPhrase === undefined ? {} : { joinPhrase }) });
const mbid = (n: number) => `00000009-0000-4000-9000-${String(n).padStart(12, '0')}`;
const subject = (name: string, n?: number): CatalogReviewCapturedSubject => ({ name, musicBrainzId: n === undefined ? null : mbid(n), revision: `${name}-revision` });
const subjects = (entries: [CatalogCredit['subjectType'], number, CatalogReviewCapturedSubject][]) => new Map(entries.map(([kind, n, value]) => [`${kind}:${subjectId(n)}`, value]));
const capture = (album: CatalogCredit[] | null, members: { slotId: string; credits: CatalogCredit[] | null; attributionStatus?: unknown }[], known: Map<string, CatalogReviewCapturedSubject>) =>
    catalogReviewCaptureOf({ reviewId, capturedAt: new Date(0), subjects: known, album: { credits: album, expectedTracklist: null },
        members: members.map(member => ({ attributionStatus: undefined, duration: null, ...member })) });

test('the captured Credits keep stored order, role, phrase and record, and name the entry showing each one', () => {
    const known = subjects([['artist', 10, subject('Synthetic A', 1)], ['artist', 11, subject('Synthetic B')], ['artist', 12, subject('Synthetic Composer')], ['organization', 30, subject('Synthetic Label', 3)]]);
    const album = [credit('c1', 'artist', 10, 'primary', ' & '), credit('c2', 'artist', 11, 'featured'), credit('c3', 'artist', 12, 'composer'), credit('o1', 'organization', 30, 'label')];
    const member = [credit('m1', 'artist', 11, 'primary', ' feat. '), credit('m2', 'artist', 10, 'featured')];
    const result = capture(album, [{ slotId: slotA, credits: member, attributionStatus: 'documented' }], known);
    assert.deepEqual(result.capture.album.credits, [
        { creditId: 'c1', subjectType: 'artist', subjectId: subjectId(10), role: 'primary', joinPhrase: ' & ', entryKey: catalogReviewEntryKey(reviewId, 'c1'), subject: subject('Synthetic A', 1) },
        { creditId: 'c2', subjectType: 'artist', subjectId: subjectId(11), role: 'featured', joinPhrase: null, entryKey: catalogReviewEntryKey(reviewId, 'c2'), subject: subject('Synthetic B') },
        { creditId: 'c3', subjectType: 'artist', subjectId: subjectId(12), role: 'composer', joinPhrase: null, entryKey: null, subject: subject('Synthetic Composer') },
        { creditId: 'o1', subjectType: 'organization', subjectId: subjectId(30), role: 'label', joinPhrase: null, entryKey: null, subject: subject('Synthetic Label', 3) }
    ]);
    // The Album's entries and label carry the records' MusicBrainz IDs; keys are those review context always derived.
    assert.deepEqual(result.album, { artists: [
        { key: catalogReviewEntryKey(reviewId, 'c1'), name: 'Synthetic A', role: 'primary', joinPhrase: ' & ', musicBrainzId: mbid(1) },
        { key: catalogReviewEntryKey(reviewId, 'c2'), name: 'Synthetic B', role: 'featured', joinPhrase: null, musicBrainzId: null }
    ], label: { name: 'Synthetic Label', musicBrainzId: mbid(3) } });
    // A member's entries are keyed per slot and name only its own Credits, never the Album's.
    const entries = result.memberArtists.get(slotA)!;
    assert.deepEqual(entries.map(({ name, role, joinPhrase, musicBrainzId }) => [name, role, joinPhrase, musicBrainzId]), [['Synthetic B', 'primary', ' feat. ', null], ['Synthetic A', 'featured', null, mbid(1)]]);
    assert.deepEqual(result.capture.members[0].credits?.map(value => value.entryKey), entries.map(entry => entry.key));
    assert.deepEqual(entries.map(entry => entry.key), ['m1', 'm2'].map(creditId => catalogReviewEntryKey(reviewId, creditId, slotA)));
    assert.deepEqual([result.capture.album.artistsComplete, result.capture.members[0].artistsComplete, result.capture.album.label], [true, true, 'first']);
    // The entries equal what review context builds from the same names and IDs.
    assert.deepEqual(result.album.artists, catalogReviewCredits(reviewId, album, new Map([[subjectId(10), 'Synthetic A'], [subjectId(11), 'Synthetic B'], [subjectId(12), 'Synthetic Composer']]),
        new Map([[subjectId(30), 'Synthetic Label']]), { musicBrainzIds: new Map([[`artist:${subjectId(10)}`, mbid(1)], [`organization:${subjectId(30)}`, mbid(3)]]) }).artists);
    assert.deepEqual(result.capture.capturedAt, new Date(0)); assert.equal(result.capture.album.expectedTracklist, null);
});

test('the label state is none without a label Credit, first when its first label Credit is shown, and other otherwise', () => {
    const known = subjects([['artist', 10, subject('Synthetic A')], ['organization', 30, subject('Synthetic Label')], ['organization', 31, subject('Second Synthetic Label')], ['organization', 32, subject('Synthetic Publisher')]]);
    const artist = credit('c1', 'artist', 10, 'primary'), label = (n: number, id = `o${n}`) => credit(id, 'organization', n, 'label');
    const state = (album: CatalogCredit[] | null) => { const result = capture(album, [], known); return [result.capture.album.label, result.album.label?.name ?? null]; };
    assert.deepEqual(state([artist]), ['none', null]);
    assert.deepEqual(state([artist, credit('p1', 'organization', 32, 'publisher')]), ['none', null], 'another Organization role is not a label');
    assert.deepEqual(state([artist, label(30), label(31)]), ['first', 'Synthetic Label']);
    // The first label Credit's record is not ready: the shown label is another Credit, so the label is read-only.
    assert.deepEqual(state([artist, label(33), label(31)]), ['other', 'Second Synthetic Label']);
    assert.deepEqual(state([artist, label(33)]), ['other', null]);
    // A record whose name is empty is never shown either.
    const blank = capture([label(30)], [], subjects([['organization', 30, subject('')]]));
    assert.deepEqual([blank.capture.album.label, blank.album.label], ['other', null]);
    // Unreadable Credits show nothing and make the label read-only.
    assert.deepEqual(state(null), ['other', null]);
    assert.deepEqual(state([]), ['none', null]);
});

test('a list is complete only when every primary and featured Artist Credit is shown', () => {
    const many = Array.from({ length: 21 }, (_, index) => credit(`p${index}`, 'artist', 100 + index, 'primary'));
    const known = subjects([...many.map((value, index) => ['artist', 100 + index, subject(`Synthetic ${index}`)] as [CatalogCredit['subjectType'], number, CatalogReviewCapturedSubject]),
        ['artist', 10, subject('Synthetic A')], ['artist', 11, subject('SYNTHETIC A')], ['artist', 12, subject('Synthetic Performer')], ['artist', 13, subject('Synthetic B')]]);
    const complete = (credits: CatalogCredit[] | null) => capture(credits, [{ slotId: slotA, credits }], known).capture;
    const both = (credits: CatalogCredit[] | null) => { const value = complete(credits); return [value.album.artistsComplete, value.members[0].artistsComplete]; };
    assert.deepEqual(both(many.slice(0, 20)), [true, true]);
    // The twenty-first is never shown (at most 20 entries).
    assert.deepEqual(both(many), [false, false]);
    assert.deepEqual(complete(many).album.credits?.[20].entryKey, null);
    // A name another Credit already shows is shown once; the byline does the same, so the list is not complete.
    assert.deepEqual(both([credit('a', 'artist', 10, 'primary'), credit('b', 'artist', 10, 'featured')]), [false, false], 'one Artist twice');
    assert.deepEqual(both([credit('a', 'artist', 10, 'primary'), credit('b', 'artist', 13, 'featured')]), [true, true]);
    // Names are compared exactly, as review context compares them.
    assert.deepEqual(both([credit('a', 'artist', 10, 'primary'), credit('b', 'artist', 11, 'featured')]), [true, true]);
    // A Credit whose record is not ready is captured without a subject and is not shown.
    const unready = complete([credit('a', 'artist', 10, 'primary'), credit('u', 'artist', 99, 'featured')]);
    assert.deepEqual([unready.album.artistsComplete, unready.album.credits?.[1].subject, unready.album.credits?.[1].entryKey], [false, null, null]);
    // Credits of other roles never count.
    assert.deepEqual(both([credit('a', 'artist', 12, 'performer'), credit('u', 'artist', 99, 'composer')]), [true, true]);
    // Unreadable Credits are never complete.
    const unreadable = complete(null);
    assert.deepEqual([unreadable.album.credits, unreadable.album.artistsComplete, unreadable.members[0].credits, unreadable.members[0].artistsComplete], [null, false, null, false]);
});

test('legacy unspecified Credits are captured but shown as no entry, and leave a list complete', () => {
    const known = subjects([['artist', 10, subject('Synthetic Legacy')], ['artist', 11, subject('Synthetic Primary')]]);
    const legacy = [credit('l1', 'artist', 10, 'legacyUnspecified')];
    const result = capture(null, [{ slotId: slotA, credits: legacy, attributionStatus: 'documented' }, { slotId: slotB, credits: [...legacy, credit('p1', 'artist', 11, 'primary')] }], known);
    assert.deepEqual(result.memberArtists.get(slotA), []);
    assert.deepEqual(result.capture.members[0].credits, [{ creditId: 'l1', subjectType: 'artist', subjectId: subjectId(10), role: 'legacyUnspecified', joinPhrase: null, entryKey: null, subject: subject('Synthetic Legacy') }]);
    assert.equal(result.capture.members[0].artistsComplete, true);
    assert.deepEqual(result.memberArtists.get(slotB)?.map(entry => entry.name), ['Synthetic Primary']);
    assert.equal(result.capture.members[1].artistsComplete, true);
    // A member without Credits is complete with no entries.
    const empty = capture([], [{ slotId: slotA, credits: [] }], known);
    assert.deepEqual([empty.memberArtists.get(slotA), empty.capture.members[0].artistsComplete, empty.capture.album.artistsComplete], [[], true, true]);
});

test('captured entries keep stored Credit order, a featured Artist before a primary one included, and names differing only in case', () => {
    // Captured lists are catalog context: compared by position later and never re-parsed as a proposed value would be.
    const known = subjects([['artist', 10, subject('Synthetic Featured')], ['artist', 11, subject('Synthetic Primary')], ['artist', 12, subject('SYNTHETIC PRIMARY')]]);
    const member = [credit('f1', 'artist', 10, 'featured', ' with '), credit('p1', 'artist', 11, 'primary', ' & '), credit('p2', 'artist', 12, 'primary')];
    const result = capture([], [{ slotId: slotA, credits: member }], known);
    assert.deepEqual(result.memberArtists.get(slotA)?.map(entry => [entry.name, entry.role, entry.joinPhrase]),
        [['Synthetic Featured', 'featured', ' with '], ['Synthetic Primary', 'primary', ' & '], ['SYNTHETIC PRIMARY', 'primary', null]]);
    assert.deepEqual(result.capture.members[0].credits?.map(value => value.creditId), ['f1', 'p1', 'p2']);
    assert.equal(result.capture.members[0].artistsComplete, true);
});

test('a member\'s attribution state keeps an explicit unknown apart from an absent or unrecognized one', () => {
    const states: [unknown, 'documented' | 'unknown' | null][] = [['documented', 'documented'], ['unknown', 'unknown'], [undefined, null], [null, null], ['Documented', null], ['', null], [1, null], [{}, null]];
    const result = capture([], states.map(([attributionStatus], index) => ({ slotId: `00000009-0000-4000-a000-${String(index).padStart(12, '0')}`, credits: [], attributionStatus })), new Map());
    assert.deepEqual(result.capture.members.map(member => member.attributionStatus), states.map(([, expected]) => expected));
    // Members keep source order and their durations.
    assert.deepEqual(result.capture.members.map(member => member.slotId), states.map((_, index) => `00000009-0000-4000-a000-${String(index).padStart(12, '0')}`));
    const timed = catalogReviewCaptureOf({ reviewId, capturedAt: new Date(0), subjects: new Map(), album: { credits: [], expectedTracklist: [{ discNumber: 1, trackNumber: 1, title: 'One', durationMs: null }] },
        members: [{ slotId: slotA, credits: [], attributionStatus: 'unknown', duration: { durationMs: 1_000, durationPrecisionMs: 1000 } }] });
    assert.deepEqual(timed.capture.members[0].duration, { durationMs: 1_000, durationPrecisionMs: 1000 });
    assert.deepEqual(timed.capture.album.expectedTracklist, [{ discNumber: 1, trackNumber: 1, title: 'One', durationMs: null }]);
});

test('a member\'s duration is its exact media duration, else its legacy whole-second text, else unknown', () => {
    assert.deepEqual(catalogReviewMemberDuration({ mediaRepresentation: { durationMs: 185_123 }, duration: '3:05' }), { durationMs: 185_123, durationPrecisionMs: 0 });
    assert.deepEqual(catalogReviewMemberDuration({ mediaRepresentation: { durationMs: null }, duration: '3:05' }), { durationMs: 185_000, durationPrecisionMs: 1000 });
    assert.deepEqual(catalogReviewMemberDuration({ duration: '1:02:03' }), { durationMs: 3_723_000, durationPrecisionMs: 1000 });
    for (const representation of [{ durationMs: 0 }, { durationMs: -1 }, { durationMs: 1.5 }, { durationMs: '185123' }, { durationMs: Number.MAX_SAFE_INTEGER + 1 }, null, 'x', []]) {
        assert.deepEqual(catalogReviewMemberDuration({ mediaRepresentation: representation, duration: '0:10' }), { durationMs: 10_000, durationPrecisionMs: 1000 }, JSON.stringify(representation));
    }
    for (const duration of [undefined, null, '', '0:00', '3:5', '3:60', 185, 'x'.repeat(17)]) assert.equal(catalogReviewMemberDuration({ duration }), null, String(duration));
});
